function renderAuthScreen(e,t){var i=document.getElementById("app");i.innerHTML='<div class="auth-wrap"><p class="eyebrow" style="text-align:center;">Sunbliss Residences</p><h1 class="title" style="text-align:center;">Sales &amp; Collections</h1><div class="auth-card"><div class="auth-tabs"><div class="auth-tab active" id="tabSignIn">Sign In</div><div class="auth-tab" id="tabSignUp">Sign Up</div></div><div id="signInForm"><label class="auth-label">Email</label><input type="email" id="siEmail" class="auth-input" /><label class="auth-label">Password</label><input type="password" id="siPassword" class="auth-input" /><button class="btn btn-gold" id="btnSignIn" style="width:100%;justify-content:center;margin-top:16px;">Sign In</button></div><div id="signUpForm" class="hidden"><label class="auth-label">Full name</label><input type="text" id="suName" class="auth-input" /><label class="auth-label">Email</label><input type="email" id="suEmail" class="auth-input" /><label class="auth-label">Password (min 6 characters)</label><input type="password" id="suPassword" class="auth-input" /><button class="btn btn-gold" id="btnSignUp" style="width:100%;justify-content:center;margin-top:16px;">Create Account</button></div>'+(e?'<div class="auth-msg '+(t?"auth-msg-ok":"auth-msg-error")+'">'+esc(e)+"</div>":"")+"</div></div>",document.getElementById("tabSignIn").onclick=function(){document.getElementById("tabSignIn").classList.add("active"),document.getElementById("tabSignUp").classList.remove("active"),document.getElementById("signInForm").classList.remove("hidden"),document.getElementById("signUpForm").classList.add("hidden")},document.getElementById("tabSignUp").onclick=function(){document.getElementById("tabSignUp").classList.add("active"),document.getElementById("tabSignIn").classList.remove("active"),document.getElementById("signUpForm").classList.remove("hidden"),document.getElementById("signInForm").classList.add("hidden")},document.getElementById("btnSignIn").onclick=async function(){var s=document.getElementById("siEmail").value.trim(),n=document.getElementById("siPassword").value;if(!s||!n){renderAuthScreen("Enter your email and password.",!1);return}var{error:a}=await sb.auth.signInWithPassword({email:s,password:n});if(a){renderAuthScreen(a.message,!1);return}boot()},document.getElementById("btnSignUp").onclick=async function(){var s=document.getElementById("suName").value.trim(),n=document.getElementById("suEmail").value.trim(),a=document.getElementById("suPassword").value;if(!s||!n||!a){renderAuthScreen("Fill in every field.",!1);return}if(a.length<6){renderAuthScreen("Password must be at least 6 characters.",!1);return}var{error:l}=await sb.auth.signUp({email:n,password:a,options:{data:{full_name:s}}});if(l){renderAuthScreen(l.message,!1);return}boot()}}async function boot(){var{data:{user:e}}=await sb.auth.getUser();if(!e){renderAuthScreen();return}try{var{data:t}=await sb.from("profiles").select("full_name, role").eq("id",e.id).single();state.userName=t&&t.full_name||e.email,state.userRole=t?t.role:"manager",await loadFromSupabase(),render()}catch(i){document.getElementById("app").innerHTML='<div class="auth-wrap"><p class="auth-msg auth-msg-error">Could not load your portfolio: '+esc(i.message||String(i))+"</p></div>"}}document.addEventListener("DOMContentLoaded",boot);